import {
  Form,
  Input,
  Checkbox,
  Link,
  Button,
  Space,
  Image,
} from '@arco-design/web-react';
import { FormInstance } from '@arco-design/web-react/es/Form';
import { IconLock, IconSafe, IconUser } from '@arco-design/web-react/icon';
import React, { useEffect, useRef, useState } from 'react';
import _ from 'lodash'
import i18next from 'i18next';
import useStorage from '@/utils/useStorage';
import styles from './style/index.module.less';
import ajax from '../../utils/ajax';
import { aseDecrypt, aseEncrypt, generateRandomString } from '../../utils/crypto';
import user from '../../store/user';
import utils from 'utils';
import { useHistory } from 'react-router-dom';
import app from '../../store/app';

const { t } = i18next;

export default function LoginForm() {
  const [errorMessage, setErrorMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [loginParams, setLoginParams, removeLoginParams] = useStorage(`${app.tenantId}-loginParams`);
  const [verify, setVerify] = useState<any>({});
  const history = useHistory();
  const [form] = Form.useForm();


  const [rememberPassword, setRememberPassword] = useState(!!loginParams);

  async function afterLoginSuccess(params) {
    // 记住密码
    if (rememberPassword) {
      const key = await generateRandomString()
      setLoginParams(JSON.stringify({ key, value: await aseEncrypt(key, params)}));
    } else {
      removeLoginParams();
    }
    // 记录登录状态
    const { redirect } = utils.getAllQueryParam();
    if(redirect){
      window.location.href = decodeURIComponent(redirect);
    }else {
      // 跳转首页
      history.push('/admin')
    }
  }

  function login(params) {
    setErrorMessage('');
    setLoading(true);
    ajax.post('/user/login', params, {
        encrypt: "all"
      })
      .then((res) => {
        const { code, data, msg } = res;
        if (!code) {
          user.setInfo(data);
          afterLoginSuccess(_.pick(params, ['loginname', 'password']));
        }
      })
      .finally(() => {
        setLoading(false);
        getVerify();
      });
  }

  function onSubmitClick() {
    form.validate().then((values) => {
      console.log('values', values)
      login({
        ...values,
        verifyId: verify.id,
      });
    });
  }

  const getVerify = () => {
    ajax.get('/captcha/code').then((res) => {
      setVerify(res.data)
    })
  }

  useEffect(() => {
    getVerify();
  },[])


  // 读取 localStorage，设置初始值
  useEffect(() => {
    if(rememberPassword){
      setRememberPassword(rememberPassword);
      // console.log('setRememberPassword', formRef.current, rememberPassword)
      if (rememberPassword) {
        const { key, value } = JSON.parse(loginParams);
        aseDecrypt(key, value).then((data) => {
          form.setFieldsValue(data);
        })
      }
    }
  }, []);

  return (
    <div className={styles['login-form-wrapper']}>
      <div className={styles['login-form-title']}>
        {t('admin.system')}
      </div>
      {/* <div className={styles['login-form-sub-title']}>
        {t['login.form.title']}
      </div> */}
      <div className={styles['login-form-error-msg']}>{errorMessage}</div>
      <Form
        form={form}
        className={styles['login-form']}
        layout="vertical"
        initialValues={{ loginname: '', password: '' }}
      >
        <Form.Item
          field="loginname"
          rules={[{ required: true, message: t('username.empty') }]}
        >
          <Input size="large"
            prefix={<IconUser />}
            placeholder={t('enter.username')}
            onPressEnter={onSubmitClick}
          />
        </Form.Item>
        <Form.Item
          field="password"
          rules={[{ required: true, message: t('password.empty') }]}
        >
          <Input.Password size="large"
            prefix={<IconLock />}
            placeholder={t('enter.password')}
            onPressEnter={onSubmitClick}
          />
        </Form.Item>
        <Space>
          <Form.Item
            field="verifyCode"
            rules={[{ required: true, message: t('input.captcha') }]}
          >
            <Input size="large" prefix={<IconSafe />} placeholder={t('sys.captcha')} autoComplete="off" />
          </Form.Item>
          <div 
            className={styles['login-form-verify']}
            dangerouslySetInnerHTML={{ __html: verify.data }}
            onClick={() => getVerify()}
          ></div>
        </Space>
        <Space size={16} direction="vertical">
          {/* <div className={styles['login-form-password-actions']}>
            <Checkbox checked={rememberPassword} onChange={setRememberPassword}>
              {t('remember.password')}
            </Checkbox>
          </div> */}
          <Button type="primary" long onClick={onSubmitClick} loading={loading}>
            {t('sys.login')}
          </Button>
        </Space>
      </Form>
    </div>
  );
}
